-- Batch 11: the rest of the rebuilt missing enchants. Their target shares its spell flag with many other
-- spells, so instead of a flag each spell has no class mask and names its targets in wcme_spellaffect_dbc
-- (every spell of that name in that class). Needs the build with patch mystic-enchants-spellaffect-sql, which
-- loads that table into the server's SpellAffect data; on an older build these spells change nothing.
CREATE TEMPORARY TABLE `wcme_new_spell` (`id` INT NOT NULL PRIMARY KEY);
DELETE FROM `wcme_new_spell` WHERE `id` IN (SELECT `ID` FROM `spell_dbc`);
DROP TEMPORARY TABLE `wcme_new_spell`;
